function makeMarker(color, size) {
  var m = draw.marker(size, size, function (add) {
    add.path('M 0 0 L ' + size + ' ' + (size / 2) + ' L 0 ' + size + ' z').fill(color);
  });
  m.ref(size, size / 2);
  m.attr({ orient: 'auto', markerUnits: 'strokeWidth' });
  return m;
}

function computeGeometry() {
  var r = objectRatio;
  var qRatio = r / (r - 1);
  var needRight = r > 1 ? Math.abs(qRatio) : 1.35;
  var needLeft = r < 1 ? Math.max(r, Math.abs(qRatio)) : r;
  var fpx = Math.min(baseFpx, 365 / Math.max(needLeft, 0.1), 245 / Math.max(needRight, 0.1));
  fpx = Math.max(27, fpx);

  var doPx = r * fpx;
  var diPx = qRatio * fpx;
  var m = -qRatio / r;
  var ho = Math.min(108, 132 / Math.max(1, Math.abs(m)));
  var hi = m * ho;

  return {
    r: r,
    qRatio: qRatio,
    fpx: fpx,
    doPx: doPx,
    diPx: diPx,
    m: m,
    ho: ho,
    hi: hi,
    objX: lensX - doPx,
    imgX: lensX + diPx,
    objTipY: axisY - ho,
    imgTipY: axisY - hi,
    nearF: lensX - fpx,
    farF: lensX + fpx,
    real: r > 1
  };
}

function label(txt, x, y, color, size, anchor) {
