function italicLabel(txt, x, y, color, size, anchor) {
  var t = label(txt, x, y, color, size || 18, anchor);
  t.font({ family: 'Times New Roman, serif', style: 'italic' });
  return t;
}

function lineWithArrow(x1, y1, x2, y2, color, width, marker, dash) {
  var l = draw.line(x1, y1, x2, y2)
    .stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' });
  if (dash) l.attr({ 'stroke-dasharray': dash });
  if (marker) l.marker('end', marker);
  return l;
}

function twoEndedBracket(x1, y1, x2, y2, text, lx, ly) {
  var blackEnd = makeMarker('#111', 7);
  var blackStart = makeMarker('#111', 7);
  blackStart.attr({ orient: 'auto-start-reverse', markerUnits: 'strokeWidth' });
  var l = draw.line(x1, y1, x2, y2).stroke({ color: '#111', width: 1.4 });
  l.marker('start', blackStart).marker('end', blackEnd);
  italicLabel(text, lx, ly, '#111', 18);
  return l;
}

function tick(x1, y1, x2, y2) {
  draw.line(x1, y1, x2, y2).stroke({ color: '#111', width: 1.2 });
}

function extendToX(p1, p2, x) {
  var dx = p2.x - p1.x;
  if (Math.abs(dx) < 0.0001) return { x: x, y: p2.y };
  return { x: x, y: p1.y + (p2.y - p1.y) * ((x - p1.x) / dx) };
}

function rayOpacity(n) {
  return selectedRay && selectedRay !== n ? 0.18 : 1;
}

function addRayHit(el, n) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Click ray ' + n + ' to isolate its construction rule.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      selectedRay = selectedRay === n ? null : n;
      render();
      showPopup(rayInfo[n].title, rayInfo[n].body);
    });
}

function drawRaySegment(x1, y1, x2, y2, color, width, marker, dash, n) {
  var visible = lineWithArrow(x1, y1, x2, y2, color, width, marker, dash).opacity(rayOpacity(n));
  var hit = draw.line(x1, y1, x2, y2).stroke({ color: '#000', width: 14, opacity: 0 }).fill('none');
  addRayHit(hit, n);
  return visible;
}

function drawArrowVertical(x, yBase, yTip, color, width) {
  var marker = makeMarker(color, 9);
  lineWithArrow(x, yBase, x, yTip, color, width, marker);
}

function drawLens(g) {
  draw.path('M 395 7 C 378 77 374 286 395 358 L 426 358 C 445 286 442 77 426 7 Z')
    .fill({ color: '#c9d9dc', opacity: 0.92 })
    .stroke({ color: '#0c83a8', width: 1.1 });
  draw.line(lensX, 7, lensX, 358).stroke({ color: '#555', width: 1.2, dasharray: '8 7' });
}

function drawMeasurements(g) {
  var geom = g;
  if (!showMeasurements) return;

  var yDist = axisY + 110;
  var objBracketX = Math.max(18, geom.objX - 36);
  var imgBracketX = geom.real ? Math.min(W - 24, geom.imgX + 34) : Math.max(22, geom.imgX - 34);
  var imgLabelX = geom.real ? imgBracketX + 25 : imgBracketX - 25;

  tick(geom.objX, yDist - 13, geom.objX, yDist + 13);
  tick(lensX, yDist - 13, lensX, yDist + 13);
  twoEndedBracket(geom.objX, yDist, lensX, yDist, 'dₒ', (geom.objX + lensX) / 2, yDist + 20);

  var yDi = yDist;
  tick(geom.imgX, yDi - 13, geom.imgX, yDi + 13);
  twoEndedBracket(lensX, yDi, geom.imgX, yDi, 'dᵢ', (lensX + geom.imgX) / 2, yDi + 20);

  var yF = axisY - 23;
  tick(lensX, yF - 12, lensX, yF + 12);
  tick(geom.farF, yF - 12, geom.farF + 0.1, yF + 12);
  twoEndedBracket(lensX, yF, geom.farF, yF, 'f', (lensX + geom.farF) / 2, yF - 18);

  tick(objBracketX - 8, axisY, objBracketX + 8, axisY);
  tick(objBracketX - 8, geom.objTipY, objBracketX + 8, geom.objTipY);
  twoEndedBracket(objBracketX, axisY, objBracketX, geom.objTipY, 'hₒ', objBracketX - 18, (axisY + geom.objTipY) / 2);

  tick(imgBracketX - 8, axisY, imgBracketX + 8, axisY);
  tick(imgBracketX - 8, geom.imgTipY, imgBracketX + 8, geom.imgTipY);
  twoEndedBracket(imgBracketX, axisY, imgBracketX, geom.imgTipY, 'hᵢ', imgLabelX, (axisY + geom.imgTipY) / 2);
}

function render() {
  draw.clear();

  var geom = computeGeometry();
  var red = '#e23b3b', green = '#7ca828', purple = '#8061a2';
  var redMarker = makeMarker(red, 9);
  var greenMarker = makeMarker(green, 9);
  var purpleMarker = makeMarker(purple, 9);

  draw.line(0, axisY, W, axisY).stroke({ color: '#111', width: 1.1 });
  drawLens();

  draw.circle(8).center(geom.nearF, axisY).fill('#d94145');
  draw.circle(8).center(geom.farF, axisY).fill('#d94145');
  italicLabel('F', geom.nearF - 13, axisY + 15, '#111', 19);
  italicLabel('F', geom.farF - 12, axisY + 15, '#111', 19);

  drawArrowVertical(geom.objX, axisY, geom.objTipY, '#d94145', 6);
  drawArrowVertical(geom.imgX, axisY, geom.imgTipY, '#d94145', 5);
  draw.circle(8).center(geom.imgX, geom.imgTipY).fill('#d94145').opacity(0.85);

  var lensAtRay1 = { x: lensX, y: geom.objTipY };
  var lensAtRay3 = { x: lensX, y: geom.imgTipY };

  if (geom.real) {
    var redEnd = extendToX(lensAtRay1, { x: geom.farF, y: axisY }, W - 28);
    var greenEnd = extendToX({ x: geom.objX, y: geom.objTipY }, { x: lensX, y: axisY }, W - 30);
    var purpleEnd = { x: W - 28, y: geom.imgTipY };

    drawRaySegment(geom.objX, geom.objTipY, lensX, geom.objTipY, red, 2.1, null, null, 1);
    drawRaySegment(lensX, geom.objTipY, redEnd.x, redEnd.y, red, 2.1, redMarker, null, 1);

    drawRaySegment(geom.objX, geom.objTipY, greenEnd.x, greenEnd.y, green, 2.1, greenMarker, null, 2);

    drawRaySegment(geom.objX, geom.objTipY, lensX, geom.imgTipY, purple, 2.1, null, null, 3);
    drawRaySegment(lensX, geom.imgTipY, purpleEnd.x, purpleEnd.y, purple, 2.1, purpleMarker, null, 3);
  } else {
    var redOut = extendToX(lensAtRay1, { x: geom.farF, y: axisY }, W - 28);
    var greenOut = extendToX({ x: geom.imgX, y: geom.imgTipY }, { x: lensX, y: axisY }, W - 28);
    var purpleOut = { x: W - 28, y: geom.imgTipY };

    drawRaySegment(geom.objX, geom.objTipY, lensX, geom.objTipY, red, 2.1, null, null, 1);
    drawRaySegment(lensX, geom.objTipY, redOut.x, redOut.y, red, 2.1, redMarker, null, 1);
    draw.line(geom.imgX, geom.imgTipY, lensX, geom.objTipY).stroke({ color: red, width: 1.5, dasharray: '6 5' }).opacity(rayOpacity(1) * 0.75);

    drawRaySegment(lensX, axisY, greenOut.x, greenOut.y, green, 2.1, greenMarker, null, 2);
    draw.line(geom.imgX, geom.imgTipY, lensX, axisY).stroke({ color: green, width: 1.5, dasharray: '6 5' }).opacity(rayOpacity(2) * 0.75);

    drawRaySegment(geom.objX, geom.objTipY, lensX, geom.imgTipY, purple, 2.1, null, null, 3);
    drawRaySegment(lensX, geom.imgTipY, purpleOut.x, purpleOut.y, purple, 2.1, purpleMarker, null, 3);
    draw.line(geom.imgX, geom.imgTipY, lensX, geom.imgTipY).stroke({ color: purple, width: 1.5, dasharray: '6 5' }).opacity(rayOpacity(3) * 0.75);
  }

  label('1', lensX - 170, Math.max(24, geom.objTipY - 15), red, 18).opacity(rayOpacity(1));
  label('2', lensX - 170, axisY - 78, green, 18).opacity(rayOpacity(2));
  label('3', lensX - 226, axisY - 39, purple, 18).opacity(rayOpacity(3));

  drawMeasurements(geom);

  var status = geom.real ? 'real inverted image' : 'virtual upright image';
  label(status, W - 132, 28, '#333', 13, 'middle')
    .fill(geom.real ? '#8b1e1e' : '#244f8f');

  var read = document.getElementById('calcReadout');
  if (read) {
    var diText = geom.real ? geom.qRatio.toFixed(2) + ' f' : '−' + Math.abs(geom.qRatio).toFixed(2) + ' f';
    var hiSign = geom.hi < 0 ? '−' : '+';
    read.innerHTML = 'Lens equation: d<sub>i</sub> = ' + diText +
      '<br>Magnification: m = ' + geom.m.toFixed(2) +
      '<br>h<sub>i</sub> = ' + hiSign + Math.abs(geom.m).toFixed(2) + ' h<sub>o</sub>';
  }
}

function update_objectDistance(v) {
  objectRatio = v;
  selectedRay = null;
  render();
}

function toggle_measurementOverlay(on) {
  showMeasurements = !!on;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  var state = step.state || {};

  if (state.objectDistance != null) {
    objectRatio = +state.objectDistance;
    var s = document.getElementById('objectDistanceInput');
    var o = document.getElementById('objectDistanceVal');
    if (s) s.value = objectRatio;
    if (o) o.value = objectRatio;
  }

  showMeasurements = state.measurementOverlay === 'Measurements';
  var c = document.getElementById('measurementOverlayInput');
  if (c) c.checked = showMeasurements;

  selectedRay = null;
  render();

  var n = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (n) n.textContent = step.narration;
  if (lab) lab.textContent = (currentStep + 1) + ' / ' + demoSteps.length + ': ' + step.title;
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A converging lens forms an image where the three principal rays from an object point meet, and the lens equation makes image distance and magnification change predictably as object distance changes.
KEY INSIGHT (what students should walk away understanding): The image is not chosen arbitrarily: it is the single point where independently constructed principal rays agree, and its distance and height shift as d_o changes according to the lens equation.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A converging lens forms an image where the three principal rays from an object point meet, and the lens equation makes image distance and magnification change predictably as object distance changes.",
  "figureType": "diagram",
  "elements": [
    "horizontal optical axis through the lens center",
    "upright biconvex converging lens shaded pale blue",
    "vertical dashed center line through the lens",
    "left focal point on the optical axis marked with a red dot and labeled F",
    "right focal point on the optical axis marked with a red dot and labeled F",
    "object arrow on the left of the lens, red, upright, with its tip above the optical axis",
    "image arrow on the right or left depending on object distance, red, inverted for real image and upright for virtual image",
    "ray 1 in red: leaves object tip parallel to optical axis, refracts through the far focal point",
    "ray 2 in green: leaves object tip and passes straight through the lens center without bending",
    "ray 3 in purple: leaves object tip through the near focal point, refracts parallel to the optical axis",
    "ray labels 1, 2, and 3 near their corresponding rays",
    "common ray intersection point marking the image tip",
    "height bracket labeled h_o beside the object",
    "height bracket labeled h_i beside the image",
    "object-distance bracket labeled d_o from the object to the lens center",
    "image-distance bracket labeled d_i from the lens center to the image",
    "focal-length bracket labeled f from the lens center to the right focal point",
    "optional dashed backward ray extensions for virtual-image cases",
    "small status label indicating real inverted image or virtual upright image"
  ],
  "interactions": [
    {
      "id": "objectDistance",
      "type": "slider",
      "label": "Object distance d_o / f",
      "range": [
        0.6,
        5,
        0.1
      ],
      "default": 2.5,
      "teaches": "Moving the object changes where the refracted rays meet, showing the tradeoff between object distance, image distance, and image height predicted by the lens equation"
    },
    {
      "id": "selectPrincipalRay",
      "type": "click",
      "teaches": "Each principal ray follows a different simple construction rule, yet all valid rays from the same object point agree on the same image point"
    },
    {
      "id": "measurementOverlay",
      "type": "toggle",
      "label": "View",
      "options": [
        "Ray construction",
        "Measurements"
      ],
      "default": "Ray construction",
      "teaches": "The drawn distances and heights correspond directly to the variables in the thin-lens and magnification equations"
    }
  ],
  "demo_steps": [
    {
      "title": "Construct the image from three rays",
      "narration": "With the object outside the focal length, the red, green, and purple principal rays meet on the far side of the lens. Their intersection fixes a real, inverted image that could be caught on a screen.",
      "state": {
        "objectDistance": 2.5,
        "measurementOverlay": "Ray construction"
      }
    },
    {
      "title": "Inspect the ray rules",
      "narration": "Click each ray to isolate its rule: ray 1 bends through the far focus, ray 2 passes through the center unchanged, and ray 3 emerges parallel after passing through the near focus.",
      "state": {
        "objectDistance": 2.5,
        "measurementOverlay": "Ray construction"
      }
    },
    {
      "title": "Measure the geometry",
      "narration": "Turn on the measurement overlay to see d_o, d_i, f, h_o, and h_i attached to the construction. The image height is negative relative to the object because the real image is inverted.",
      "state": {
        "objectDistance": 2.5,
        "measurementOverlay": "Measurements"
      }
    },
    {
      "title": "Move the object toward the focal point",
      "narration": "As d_o approaches f from the outside, the refracted rays meet farther away and the inverted image grows larger. This makes the lens-equation tradeoff visible without doing algebra first.",
      "state": {
        "objectDistance": 1.2,
        "measurementOverlay": "Measurements"
      }
    },
    {
      "title": "Move inside the focal length",
      "narration": "When the object is closer than one focal length, the outgoing rays no longer meet on the far side. Their dashed backward extensions meet on the object side, giving a virtual upright image.",
      "state": {
        "objectDistance": 0.7,
        "measurementOverlay": "Measurements"
      }
    }
  ],
  "keyInsight": "The image is not chosen arbitrarily: it is the single point where independently constructed principal rays agree, and its distance and height shift as d_o changes according to the lens equation.",
  "reconstructionNotes": "Use a clean 2D optical-axis layout matching the textbook figure: lens centered vertically, object on the left, real image on the right when d_o > f. Keep ray colors consistent: ray 1 red, ray 2 green, ray 3 purple. The lens should be pale blue with a dashed vertical center line. Focal points should be red dots labeled F on both sides of the lens. In measurement mode, show black bracket arrows for f, d_o, d_i, h_o, and h_i; in ray-construction mode, keep those brackets hidden or subdued. When d_o crosses inside f, show refracted rays diverging on the right and dashed backward extensions meeting on the left at a virtual upright image."
}

