// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 680, H = 360;
draw.viewbox(0, 0, W, H);

var axisY = 185;
var lensX = 410;
var baseFpx = 120;
var objectRatio = 2.5;
var showMeasurements = true;
var selectedRay = null;
var currentStep = 0;

var rayInfo = {
  1: {
    title: 'Ray 1: parallel then through focus',
