];

function makeMarker(color, size) {
  var m = draw.marker(size, size, function (add) {
    add.path('M 0 0 L ' + size + ' ' + (size / 2) + ' L 0 ' + size + ' z').fill(color);
  });
  m.ref(size, size / 2);
  m.attr({ orient: 'auto', markerUnits: 'strokeWidth' });
  return m;
}

function makeStartMarker(color, size) {
  var m = makeMarker(color, size);
  m.attr({ orient: 'auto-start-reverse', markerUnits: 'strokeWidth' });
  return m;
}

function computeGeometry() {
  var r = objectRatio;
  var qRatio = r / (r - 1);
  var needLeft = r < 1 ? Math.max(r, Math.abs(qRatio)) : r;
  var needRight = r > 1 ? Math.abs(qRatio) : 1.55;

  var fpx = Math.min(
    baseFpx,
    (lensX - 48) / Math.max(needLeft, 0.12),
    (W - lensX - 38) / Math.max(needRight, 0.12)
  );
  fpx = Math.max(30, fpx);

  var doPx = r * fpx;
  var diPx = qRatio * fpx;
  var m = -qRatio / r;

  var ho = Math.min(112, 142 / Math.max(1, Math.abs(m)));
  var hi = m * ho;

  return {
    r: r,
    qRatio: qRatio,
    fpx: fpx,
    doPx: doPx,
    diPx: diPx,
    m: m,
    ho: ho,
    hi: hi,
    objX: lensX - doPx,
    imgX: lensX + diPx,
    objTipY: axisY - ho,
    imgTipY: axisY - hi,
    nearF: lensX - fpx,
    farF: lensX + fpx,
    real: r > 1
  };
}

function label(txt, x, y, color, size, anchor) {
  return draw.text(txt)
    .font({ family: 'Arial, sans-serif', size: size || 16, weight: 'normal' })
    .fill(color || '#111')
    .attr({
      x: x,
      y: y,
      'text-anchor': anchor || 'middle',
      'dominant-baseline': 'middle',
      'paint-order': 'stroke',
      stroke: '#fff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    });
}

function italicLabel(txt, x, y, color, size, anchor) {
  var t = label(txt, x, y, color, size || 18, anchor);
  t.font({ family: 'Times New Roman, serif', style: 'italic' });
  return t;
}

function tick(x1, y1, x2, y2) {
  draw.line(x1, y1, x2, y2).stroke({ color: '#111', width: 1.15, linecap: 'square' });
}

function twoEndedBracket(x1, y1, x2, y2, text, lx, ly) {
  var start = makeStartMarker('#111', 6);
  var end = makeMarker('#111', 6);
  var l = draw.line(x1, y1, x2, y2).stroke({ color: '#111', width: 1.25, linecap: 'round' });
  l.marker('start', start).marker('end', end);
  italicLabel(text, lx, ly, '#111', 18);
  return l;
}

function extendToX(p1, p2, x) {
  var dx = p2.x - p1.x;
  if (Math.abs(dx) < 0.0001) return { x: x, y: p2.y };
  return { x: x, y: p1.y + (p2.y - p1.y) * ((x - p1.x) / dx) };
}

function rayOpacity(n) {
  return selectedRay && selectedRay !== n ? 0.16 : 1;
}

function addRayHit(el, n) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Click ray ' + n + ' to isolate its principal-ray rule.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      selectedRay = selectedRay === n ? null : n;
      render();
      showPopup(rayInfo[n].title, rayInfo[n].body);
    });
