function drawRay(x1, y1, x2, y2, color, width, n, opts) {
  opts = opts || {};
  var op = rayOpacity(n);
  var marker = makeMarker(color, 8);

  var base = draw.line(x1, y1, x2, y2)
    .stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' })
    .opacity(op);
  if (opts.dash) base.attr({ 'stroke-dasharray': opts.dash });
  if (opts.endArrow) base.marker('end', marker);

  if (opts.midArrow && !opts.dash) {
    var t2 = opts.midT == null ? 0.48 : opts.midT;
    var t1 = Math.max(0.02, t2 - 0.18);
    var ax1 = x1 + (x2 - x1) * t1;
    var ay1 = y1 + (y2 - y1) * t1;
    var ax2 = x1 + (x2 - x1) * t2;
    var ay2 = y1 + (y2 - y1) * t2;
    draw.line(ax1, ay1, ax2, ay2)
      .stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' })
      .marker('end', marker)
