function render() {
  draw.clear();

  var geom = computeGeometry();
  var red = '#d94145';
  var green = '#75a62a';
  var purple = '#8061a2';

  draw.line(0, axisY, W, axisY).stroke({ color: '#111', width: 1.05 });
  drawLens();

  draw.circle(8).center(geom.nearF, axisY).fill('#d94145');
  draw.circle(8).center(geom.farF, axisY).fill('#d94145');
  italicLabel('F', geom.nearF - 13, axisY + 14, '#111', 19);
  italicLabel('F', geom.farF - 12, axisY + 14, '#111', 19);

  drawArrowVertical(geom.objX, axisY, geom.objTipY, red, 6);
  drawArrowVertical(geom.imgX, axisY, geom.imgTipY, red, 5);
