    var greenEnd = extendToX({ x: geom.objX, y: geom.objTipY }, { x: lensX, y: axisY }, W - 30);
    var purpleEnd = { x: W - 30, y: geom.imgTipY };

    drawRay(geom.objX, geom.objTipY, lensX, geom.objTipY, red, 2.05, 1, { midArrow: true, midT: 0.48 });
    drawRay(lensX, geom.objTipY, redEnd.x, redEnd.y, red, 2.05, 1, { midArrow: true, midT: 0.46, endArrow: true });

    drawRay(geom.objX, geom.objTipY, greenEnd.x, greenEnd.y, green, 2.05, 2, { midArrow: true, midT: 0.30, endArrow: true });

    drawRay(geom.objX, geom.objTipY, lensX, geom.imgTipY, purple, 2.05, 3, { midArrow: true, midT: 0.48 });
    drawRay(lensX, geom.imgTipY, purpleEnd.x, purpleEnd.y, purple, 2.05, 3, { midArrow: true, midT: 0.54, endArrow: true });
  } else {
    var redOut = extendToX(lensAtRay1, { x: geom.farF, y: axisY }, W - 30);
    var greenOut = extendToX({ x: geom.imgX, y: geom.imgTipY }, { x: lensX, y: axisY }, W - 30);
    var purpleOut = { x: W - 30, y: geom.imgTipY };

    drawRay(geom.objX, geom.objTipY, lensX, geom.objTipY, red, 2.05, 1, { midArrow: true, midT: 0.48 });
    drawRay(lensX, geom.objTipY, redOut.x, redOut.y, red, 2.05, 1, { midArrow: true, midT: 0.45, endArrow: true });
    draw.line(geom.imgX, geom.imgTipY, lensX, geom.objTipY)
      .stroke({ color: red, width: 1.45, dasharray: '6 5', linecap: 'round' })
      .opacity(rayOpacity(1) * 0.72);

    drawRay(geom.objX, geom.objTipY, lensX, axisY, green, 2.05, 2, { midArrow: true, midT: 0.55 });
    drawRay(lensX, axisY, greenOut.x, greenOut.y, green, 2.05, 2, { endArrow: true });
    draw.line(geom.imgX, geom.imgTipY, lensX, axisY)
      .stroke({ color: green, width: 1.45, dasharray: '6 5', linecap: 'round' })
      .opacity(rayOpacity(2) * 0.72);

    drawRay(geom.objX, geom.objTipY, lensX, geom.imgTipY, purple, 2.05, 3, { midArrow: true, midT: 0.52 });
    drawRay(lensX, geom.imgTipY, purpleOut.x, purpleOut.y, purple, 2.05, 3, { endArrow: true });
    draw.line(geom.imgX, geom.imgTipY, lensX, geom.imgTipY)
      .stroke({ color: purple, width: 1.45, dasharray: '6 5', linecap: 'round' })
      .opacity(rayOpacity(3) * 0.72);
  }

  label('1', lensX - 170, geom.objTipY - 14, red, 18).opacity(rayOpacity(1));
  label('2', lensX - 171, axisY - 77, green, 18).opacity(rayOpacity(2));
  label('3', lensX - 226, axisY - 39, purple, 18).opacity(rayOpacity(3));

  drawMeasurements(geom);

  var status = geom.real ? 'real inverted image' : 'virtual upright image';
  label(status, W - 112, 24, geom.real ? '#8b1e1e' : '#244f8f', 9, 'middle').opacity(0.55);

  var read = document.getElementById('calcReadout');
  if (read) {
    var diText = geom.real ? geom.qRatio.toFixed(2) + ' f' : '−' + Math.abs(geom.qRatio).toFixed(2) + ' f';
    var hiSign = geom.hi < 0 ? '−' : '+';
    read.innerHTML = 'Lens equation: d<sub>i</sub> = ' + diText +
      '<br>Magnification: m = ' + geom.m.toFixed(2) +
      '<br>h<sub>i</sub> = ' + hiSign + Math.abs(geom.m).toFixed(2) + ' h<sub>o</sub>';
  }
}

function update_objectDistance(v) {
  objectRatio = v;
  selectedRay = null;
  render();
}

function toggle_measurementOverlay(on) {
  showMeasurements = !!on;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  var state = step.state || {};

  if (state.objectDistance != null) {
    objectRatio = +state.objectDistance;
    var s = document.getElementById('objectDistanceInput');
    var o = document.getElementById('objectDistanceVal');
    if (s) s.value = objectRatio;
    if (o) o.value = objectRatio;
  }

  if (state.measurementOverlay != null) {
    showMeasurements = state.measurementOverlay === 'Measurements';
    var c = document.getElementById('measurementOverlayInput');
    if (c) c.checked = showMeasurements;
  }

  selectedRay = null;
  render();

  var n = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (n) n.textContent = step.narration;
  if (lab) lab.textContent = (currentStep + 1) + ' / ' + demoSteps.length + ': ' + step.title;
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

